#include "stormtty/agent_service.hpp"
#include "../src/agent/json.hpp"
#include "core_test.hpp"
using namespace stormtty;
std::string request(AgentService& s,std::string_view method){auto out=s.take_outbound();for(const auto& frame:out){auto v=agent_json::parse(frame);CHECK(v.at("method").text().find("turn/")==std::string::npos);CHECK(v.at("method").text().find("thread/")==std::string::npos);if(v.at("method").text()==method)return v.at("id").scalar;}CHECK(false);return {};}
void reply(AgentService& s,const std::string& id,const std::string& result){s.feed_stdout("{\"id\":"+id+",\"result\":"+result+"}\n");}
void connected(AgentService& s,bool signed_in=false){CHECK(s.connect("fixture",""));reply(s,request(s,"initialize"),"{\"userAgent\":\"fixture\"}");reply(s,request(s,"account/read"),signed_in?"{\"account\":{\"type\":\"chatgpt\",\"email\":\"a@example.invalid\"}}":"{\"account\":null}");CHECK(s.snapshot().connection==AgentConnection::ready);CHECK(s.take_outbound().empty());}
void login_reply(AgentService& s,const std::string& id,std::string login="login-a",std::string url="https://auth.openai.com/oauth/authorize?secret=fixture"){reply(s,id,"{\"type\":\"chatgpt\",\"loginId\":"+agent_json::quote(login)+",\"authUrl\":"+agent_json::quote(url)+"}");}
void completed(AgentService& s,std::string id,bool ok=true){s.feed_stdout("{\"method\":\"account/login/completed\",\"params\":{\"loginId\":"+agent_json::quote(id)+",\"success\":"+(ok?"true":"false")+",\"error\":\"secret should not be displayed\"}}\n");}
